from pathlib import Path
import json,statistics
p=Path(__file__).resolve().parent
summary={'method':{'host':'castle-forge','url':'http://127.0.0.1:31288/','protocol':'http/1.1','browser':'Chromium 156.0.8078.73 via installed playwright-cli 0.1.18','build':'Next 16.3.8 optimized production mode, existing repository loopback browser fixture configuration; same pinned Node 24.18.0/dependencies; no hosted Clerk/Sentry traffic','viewport':{'width':390,'height':844,'dpr':3,'mobile':True,'touch':True},'cdp':{'down_bytes_per_second':200000,'up_bytes_per_second':93750,'latency_ms':150,'cpu_rate':4},'cache':'Fresh nonpersistent context each run, browser cache cleared and disabled; no auth profile reused','order':'Three baseline runs then three candidate runs; same host/port/protocol/config/browser and exclusive shared workload lock','lcp':'Last observed first-viewport LCP after load, image decode and fonts ready, before any scroll/input; LCP element is the mobile product PNG','scroll':'From top to full document bottom, 633 CSS px per 150 ms; no tabs changed. Decode all encountered images and await document.fonts.ready; verify request completion. Same eager-image composition; no URL backgrounds/external fonts.','full_scroll_asset_completion':'Navigation-relative max responseEnd for img/css/link/script resource entries discovered through full scroll, plus document responseEnd. Covers all encountered images, CSS, scripts and fonts; excludes favicon, route-data prefetches and verification/idle after assets completed. Kept separately from loadEventEnd and scan-completion time.','transfer':'CDP Network.loadingFinished encodedDataLength summed for actual browser traffic through scan, including headers and route prefetches; Resource Timing encodedBodySize and source PNG bytes separately. First baseline run also has extra CDP bytes; all runs retained.','host_contention':'Shared lock waited 7m31s before baseline build, then held for both builds and both three-run/capture phases. Other-owner heavy work excluded cooperatively. Background nonbenchmark processes remained: baseline-start load average 5.20 and brief gog/Claude spikes; candidate-start 4.15 with lower competing CPU. Raw host snapshots retained; timing estimates may include host noise, although run ranges were narrow.','live_limit':'Local estimates do not predict absolute hosted release timings: hosted Clerk/UI/analytics requests, edge TTFB/protocol and host hardware differ. No synthetic score or live guarantee.'},'variants':{}}
for v in ['base','worktree']:
 runs=[json.loads((p/f'timings/{v}-{i}.json').read_text()) for i in [1,2,3]]
 assert all(not r.get('error') and not r['errors'] for r in runs)
 for r in runs:
  assert all(i['complete'] and i['naturalWidth'] for i in r['scrolled']['images'])
  assert not [x for x in r['requests'] if x.get('error') or x.get('status',200)>=400]
 metrics={k:{'runs':[r['metrics'][k] for r in runs],'median':statistics.median(r['metrics'][k] for r in runs)} for k in runs[0]['metrics']}
 pngs=[{'file':x['url'].split('/')[-1],'browser_transfer_bytes':x.get('transferBytes')} for x in runs[1]['requests'] if x.get('type')=='Image' and 'product-review-' in x['url']]
 summary['variants'][v]={'metrics':metrics,'product_png_browser_transfer_bytes':pngs,'raw':[f'timings/{v}-{i}.json' for i in [1,2,3]],'scanCompletedMs':[r['scanCompletedMs'] for r in runs]}
base=summary['variants']['base']['metrics'];after=summary['variants']['worktree']['metrics']
summary['delta']={k:{'candidate_minus_base':after[k]['median']-base[k]['median']} for k in base}
visual=json.loads((p/'visual-diffs.json').read_text());summary['visual']={'pairs':len(visual),'total_pixels':sum(x['totalPixels'] for x in visual),'differing_pixels':sum(x['differingPixels'] for x in visual),'max_channel_delta':max(x['maxChannelDelta'] for x in visual),'raw':'visual-diffs.json','stabilization':'Same fresh fixtures, release metadata fixed to base SHA in both builds, same system fonts/ready state. Wait finite interaction transitions to finish; align observed infinite animations only (none observed on homepage). No masks, CSS/content changes, hidden elements or tolerance.'}
a=json.loads((p/'logs/capture-base.json').read_text());b=json.loads((p/'logs/capture-worktree.json').read_text())
for av,bv in zip(a['views'],b['views']):
 for key in ['state','pricingNavigation','escapeFocus','ctaHref','cta','docs','errors']:
  assert av.get(key)==bv.get(key),(av['name'],key)
summary['functional']={'matched_views':[x['name'] for x in a['views']],'equal_dom_links_text_images':True,'menu_escape_focus_return':True,'pricing_anchor_and_menu_close':True,'signup_cta_and_fixture_route':True,'docs_route_headings':True,'page_errors':[],'limits':'No authenticated hosted session or real Clerk signup exercised; existing fixture signup boundary used. Auth, analytics, logging, errors and runtime source have zero changes. Hosted browser CI covers broader existing interaction suites.'}
(p/'measurement-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
print(json.dumps({'medians':{v:{k:x['median'] for k,x in d['metrics'].items()} for v,d in summary['variants'].items()},'visual':summary['visual']},indent=2))
